import{_ as i,H as e,f as t,i as r}from"./chunks/framework.Cvt1eIE0.js";const p=JSON.parse('{"title":"钱龙","description":"","frontmatter":{},"headers":[],"relativePath":"resume/index.md","filePath":"resume/index.md"}'),a={name:"resume/index.md"};function n(o,l,s,d,h,u){return e(),t("div",null,[...l[0]||(l[0]=[r('<h1 id="钱龙" tabindex="-1">钱龙 <a class="header-anchor" href="#钱龙" aria-label="Permalink to &quot;钱龙&quot;">​</a></h1><h2 id="数字芯片设计工程师" tabindex="-1">数字芯片设计工程师 <a class="header-anchor" href="#数字芯片设计工程师" aria-label="Permalink to &quot;数字芯片设计工程师&quot;">​</a></h2><p><strong>邮箱：</strong> <a href="mailto:1343717655@qq.com" target="_blank" rel="noreferrer">1343717655@qq.com</a><br><strong>电话：</strong> (+86) 13275897328<br><strong>所在地：</strong> 中国<br><strong>工作经验：</strong> 近 7 年</p><hr><h2 id="求职意向" tabindex="-1">求职意向 <a class="header-anchor" href="#求职意向" aria-label="Permalink to &quot;求职意向&quot;">​</a></h2><p><strong>目标职位：</strong> 高级数字芯片设计工程师 / 数字前端设计专家<br><strong>技术领域：</strong> 高速接口（PCIe/AXI）、GPGPU、SSD 控制器</p><hr><h2 id="专业技能" tabindex="-1">专业技能 <a class="header-anchor" href="#专业技能" aria-label="Permalink to &quot;专业技能&quot;">​</a></h2><ol><li><p><strong>数字前端设计全流程</strong></p><ul><li>熟练掌握数字前后端设计流程及 EDA 工具使用</li><li>精通 Verilog HDL 逻辑电路设计与实现</li></ul></li><li><p><strong>总线协议</strong></p><ul><li>精通 AMBA 总线协议（AXI/AHB/APB）</li><li>深入理解 PCIe 协议（Gen6/Gen7 FLIT 模式）</li><li>熟悉 AXI5 规范及高速接口设计</li></ul></li><li><p><strong>设计质量与综合</strong></p><ul><li>Lint 检查、CDC 跨时钟域验证</li><li>SDC 时序约束编写与 Timing Analysis/Optimization</li><li>Low Power 设计（UPF/CPF）</li><li>Design Compiler/Genus 综合</li></ul></li><li><p><strong>核心能力</strong></p><ul><li>优秀的沟通学习能力</li><li>强大的 Debug 能力</li><li>PPA（性能/功耗/面积）优化能力</li></ul></li></ol><hr><h2 id="工作经历" tabindex="-1">工作经历 <a class="header-anchor" href="#工作经历" aria-label="Permalink to &quot;工作经历&quot;">​</a></h2><h3 id="沐曦集成电路有限公司-数字-ic-设计专家" tabindex="-1">沐曦集成电路有限公司 | 数字 IC 设计专家 <a class="header-anchor" href="#沐曦集成电路有限公司-数字-ic-设计专家" aria-label="Permalink to &quot;沐曦集成电路有限公司 | 数字 IC 设计专家&quot;">​</a></h3><p><strong>2021.06 - 至今</strong></p><h4 id="pcie-7-0-endpoint-控制器项目-核心设计工程师" tabindex="-1">PCIe 7.0 Endpoint 控制器项目 | 核心设计工程师 <a class="header-anchor" href="#pcie-7-0-endpoint-控制器项目-核心设计工程师" aria-label="Permalink to &quot;PCIe 7.0 Endpoint 控制器项目 | 核心设计工程师&quot;">​</a></h4><p><strong>2026.03 - 至今</strong></p><ul><li>负责 PCIe 7.0 Endpoint 前端架构设计与模块开发</li><li>实现 128 GT/s FLIT 模式下的 TLP 解析器与流控模块</li><li>设计 AXI5 仲裁器（2 Master → 1 Slave，512-bit 数据路径，Round-Robin 仲裁）</li><li>完成模块级 Lint/CDC 检查、SDC 约束编写及综合时序收敛</li><li>面积优化：相比前代设计减少逻辑资源占用</li><li>输出完整设计文档与验证计划</li></ul><h4 id="mxg100-gpgpu-项目-ip-designer-ppa-优化" tabindex="-1">MXG100 GPGPU 项目 | IP Designer / PPA 优化 <a class="header-anchor" href="#mxg100-gpgpu-项目-ip-designer-ppa-优化" aria-label="Permalink to &quot;MXG100 GPGPU 项目 | IP Designer / PPA 优化&quot;">​</a></h4><p><strong>2022.11 - 至今</strong></p><ul><li>负责 GPGPU 项目中 INT（中断）模块的开发和交付 <ul><li>设计并实现收集 SoC 所有 Client 的中断向量</li><li>通过 AXI 接口将中断向量写入 System Memory</li><li>通过 Interrupt 信号通知 PCIe Subsystem</li></ul></li><li>负责 DMA 模块的开发 <ul><li>完成命令执行单元从串行到并行的优化</li><li>提升数据吞吐效率</li></ul></li><li>基于 Power Artist 和 Spyglass 进行 Power Optimization <ul><li>提高 SCGC（Sequential Clock Gating Cell）比例</li><li>对 MGCG（Module Gated Clock Gating）进行功能优化，显著降低功耗</li></ul></li></ul><h4 id="mxc500-gpgpu-项目-ip-designer-前端收敛负责人" tabindex="-1">MXC500 GPGPU 项目 | IP Designer / 前端收敛负责人 <a class="header-anchor" href="#mxc500-gpgpu-项目-ip-designer-前端收敛负责人" aria-label="Permalink to &quot;MXC500 GPGPU 项目 | IP Designer / 前端收敛负责人&quot;">​</a></h4><p><strong>2021.06 - 2022.11</strong></p><ul><li>负责 DMA 模块的 Owner，Ring Buffer 模块开发 <ul><li>管理 Ring Buffer 对 Command 的执行及与 RISC-V 的交互</li></ul></li><li>负责子模块 RISC-V Controller 设计 <ul><li>集成 RISC-V IP（C906）</li><li>开发 AXI2Mem Bridge 模块，实现 C906 通过 AXI 接口与外部 SRAM 的数据访问</li></ul></li><li>负责前端收敛（Front-end Convergence）工作 <ul><li>作为 Tile Owner，完成 Lint/CDC 质量检查</li><li>编写 SDC 约束，完成综合，Clean Timing Issue</li><li>交付网表至后端 PD 团队</li></ul></li><li>基于 PTpx 工具对不同阶段 Netlist 进行功耗仿真和分析 <ul><li>输出功耗评估和分析文档</li></ul></li></ul><hr><h3 id="杭州联芸科技有限公司-数字-ic-设计工程师" tabindex="-1">杭州联芸科技有限公司 | 数字 IC 设计工程师 <a class="header-anchor" href="#杭州联芸科技有限公司-数字-ic-设计工程师" aria-label="Permalink to &quot;杭州联芸科技有限公司 | 数字 IC 设计工程师&quot;">​</a></h3><p><strong>2019.07 - 2021.05</strong></p><h4 id="falcon-ssd-控制器项目-flash-controller-设计负责人" tabindex="-1">Falcon SSD 控制器项目 | Flash Controller 设计负责人 <a class="header-anchor" href="#falcon-ssd-控制器项目-flash-controller-设计负责人" aria-label="Permalink to &quot;Falcon SSD 控制器项目 | Flash Controller 设计负责人&quot;">​</a></h4><p><strong>2020.11 - 2021.05</strong></p><ul><li>作为大模块 Flash Controller Design Owner，负责 Integration 相关工作</li><li>负责制定 LD（Logical Data）模块的 Design Spec 并输出 RTL Code</li><li>负责 MPI/Scrambler/CRC IP 的 Design 升级</li><li>负责 Flash Controller Module 中 SDC/UPF Constraint 和 Quality Check <ul><li>Lint Check、CDC Check、DFT Check、Pre-SYN、CLP Check</li></ul></li></ul><h4 id="eagle-ssd-控制器项目-flash-controller-设计负责人" tabindex="-1">Eagle SSD 控制器项目 | Flash Controller 设计负责人 <a class="header-anchor" href="#eagle-ssd-控制器项目-flash-controller-设计负责人" aria-label="Permalink to &quot;Eagle SSD 控制器项目 | Flash Controller 设计负责人&quot;">​</a></h4><p><strong>2019.07 - 2020.07</strong></p><ul><li>作为 Flash Controller 模块 Design Owner，负责 Top 的 Integration</li><li>基于 RS 算法实现 Raid6 编解码的硬件设计 <ul><li>制定 Raid6 Design Spec 并输出 RTL Code</li></ul></li><li>基于 Kioxia BiCS6 实现 Randomizer/Scrambler 的硬件设计 <ul><li>制定 Design Spec 并输出 RTL Code</li></ul></li><li>负责 Flash Controller Module SDC/UPF 设计和 Qualify Check</li><li>负责解决中后端反馈的各种问题，Support DV 和 VD 的验证 Debug</li></ul><hr><h2 id="教育背景" tabindex="-1">教育背景 <a class="header-anchor" href="#教育背景" aria-label="Permalink to &quot;教育背景&quot;">​</a></h2><p><strong>安徽大学</strong> | 硕士 | 集成电路工程<br> 2016.09 - 2019.07</p><hr><h2 id="项目亮点总结" tabindex="-1">项目亮点总结 <a class="header-anchor" href="#项目亮点总结" aria-label="Permalink to &quot;项目亮点总结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>角色</th><th>关键技术</th><th>成果</th></tr></thead><tbody><tr><td>PCIe 7.0 Endpoint</td><td>核心设计</td><td>PCIe Gen7/FLIT/AXI5</td><td>128 GT/s 前端架构</td></tr><tr><td>MXG100 GPGPU</td><td>IP Owner</td><td>中断系统/DMA/低功耗</td><td>功耗优化显著</td></tr><tr><td>MXC500 GPGPU</td><td>前端负责人</td><td>RISC-V 集成/时序收敛</td><td>按时交付网表</td></tr><tr><td>Falcon SSD</td><td>模块 Owner</td><td>Flash 控制/Raid6</td><td>完整控制器设计</td></tr><tr><td>Eagle SSD</td><td>模块 Owner</td><td>编解码/集成</td><td>首款产品落地</td></tr></tbody></table><hr><h2 id="自我评价" tabindex="-1">自我评价 <a class="header-anchor" href="#自我评价" aria-label="Permalink to &quot;自我评价&quot;">​</a></h2><ul><li><strong>技术深度：</strong> 近 7 年数字前端设计经验，从 SSD 控制器到 GPGPU 再到 PCIe 高速接口，技术栈持续深化</li><li><strong>项目经验：</strong> 多次担任模块 Owner 和前端收敛负责人，具备独立承担复杂 IP 开发的能力</li><li><strong>学习能力：</strong> 快速掌握新技术（如 PCIe 7.0 FLIT 模式），并能应用于实际项目</li><li><strong>团队协作：</strong> 良好的跨团队沟通能力，能有效协调 DV、VD、后端 PD 团队推进项目</li></ul><hr><p><em>最后更新：2026-03-15</em></p>',42)])])}const c=i(a,[["render",n]]);export{p as __pageData,c as default};
